/**
 * Sync the error-codes catalog from the Shared C# project into the web app.
 *
 * The authoritative copy lives at:
 *   src/Shared/AutopilotMonitor.Shared/Resources/error-codes.json
 * (generated by tools/error-codes/generate.mjs at the repo root; never edited by hand).
 *
 * The backend (ErrorCodeCatalog.cs) embeds that file; the web app (utils/errorCodeMap.ts)
 * imports the copy this script writes to utils/error-codes.json. The copy is validated,
 * trimmed to what the browser renders and minified — it ships inside the client bundle
 * (static export), so every byte counts:
 *   - `source` keeps only its kind ("msdoc", "ime:<version>", "winerror.h", "rule:<id>",
 *     "legacy-catalog-v1"); the tooltip formatter never shows the URL.
 *   - `enforcementStates` is dropped; the backend enricher delivers those names as
 *     `enforcementStateInfo` when an event needs them.
 *
 * Run: node scripts/sync-error-codes.js (invoked from prebuild and by the generator).
 * The exported helpers are unit-tested (utils/__tests__/errorCodesSync.test.ts).
 */

const fs = require("fs");
const path = require("path");

const WEB_ROOT = path.resolve(__dirname, "..");
const REPO_ROOT = path.resolve(WEB_ROOT, "..", "..", "..");
const SOURCE = path.join(REPO_ROOT, "src", "Shared", "AutopilotMonitor.Shared", "Resources", "error-codes.json");
const DEST = path.join(WEB_ROOT, "utils", "error-codes.json");

const SCHEMA_VERSION = 2;
const CATEGORIES = [
  "msi", "win32", "com", "appx", "windows-update", "cbs", "intune-win32", "intune-mobile",
  "mdm-enrollment", "autopilot", "entra-join", "delivery-optimization",
];
const CONFIDENCES = ["high", "medium", "low"];
const KEY_PATTERN = /^(0x[0-9a-f]{8}|\d+)$/;
const SOURCE_PATTERN = /^(msdoc:https:\/\/learn\.microsoft\.com\/\S+|ime:\d+(\.\d+)+|winerror\.h|rule:[A-Z]+-[A-Z]+-\d{3}|legacy-catalog-v1)$/;

/**
 * Validate the raw catalog text. Duplicate keys are checked on the TEXT — JSON.parse keeps
 * the last duplicate silently, so a parsed object can never reveal one.
 * Returns the parsed catalog; throws with a precise message otherwise.
 */
function validate(rawText) {
  const catalog = JSON.parse(rawText);
  if (catalog.schemaVersion !== SCHEMA_VERSION) {
    throw new Error(`error-codes.json: expected schemaVersion ${SCHEMA_VERSION}, got ${catalog.schemaVersion}`);
  }
  if (!catalog.entries || typeof catalog.entries !== "object") throw new Error("error-codes.json: missing entries");

  const entriesText = rawText.slice(rawText.indexOf('"entries"'), rawText.indexOf('"enforcementStates"'));
  const seen = new Set();
  for (const m of entriesText.matchAll(/^\s{4}"([^"]+)":/gm)) {
    if (seen.has(m[1])) throw new Error(`error-codes.json: duplicate key ${m[1]}`);
    seen.add(m[1]);
  }

  for (const [key, entry] of Object.entries(catalog.entries)) {
    if (!KEY_PATTERN.test(key)) throw new Error(`error-codes.json: bad key ${key}`);
    if (typeof entry.description !== "string" || !entry.description.trim()) throw new Error(`error-codes.json: ${key} has no description`);
    if (!CONFIDENCES.includes(entry.confidence)) throw new Error(`error-codes.json: ${key} has confidence ${entry.confidence}`);
    if (!CATEGORIES.includes(entry.category)) throw new Error(`error-codes.json: ${key} has category ${entry.category}`);
    if (!SOURCE_PATTERN.test(entry.source)) throw new Error(`error-codes.json: ${key} has source ${entry.source}`);
  }
  return catalog;
}

/**
 * The browser-facing shape: same keys, shortened source, no enforcement states, and the two
 * dominant field values omitted.
 *
 * `confidence: "high"` holds for 562 of 641 rows and `source: "msdoc"` for about half, so
 * spelling them out costs ~19 KB of the client bundle to repeat two constants. They are
 * omitted here and restored on read in `utils/errorCodeMap.ts` — the rendered tooltip is
 * unchanged. Keep the two defaults in sync with that reader.
 */
const DEFAULT_CONFIDENCE = "high";
const DEFAULT_SOURCE = "msdoc";

function transform(catalog) {
  const entries = {};
  for (const [key, e] of Object.entries(catalog.entries)) {
    const source = e.source.startsWith("msdoc:") ? "msdoc" : e.source;
    const out = { description: e.description };
    if (e.confidence !== DEFAULT_CONFIDENCE) out.confidence = e.confidence;
    if (source !== DEFAULT_SOURCE) out.source = source;
    out.category = e.category;
    if (e.symbol) out.symbol = e.symbol;
    if (e.imeRetriesDuringEsp) out.imeRetriesDuringEsp = true;
    entries[key] = out;
  }
  return { schemaVersion: catalog.schemaVersion, entries };
}

function sync() {
  if (!fs.existsSync(SOURCE)) {
    console.error(`[sync-error-codes] Source not found: ${SOURCE}`);
    process.exit(1);
  }
  const catalog = validate(fs.readFileSync(SOURCE, "utf8"));
  const output = JSON.stringify(transform(catalog));
  fs.writeFileSync(DEST, output + "\n", "utf8");
  console.log(`[sync-error-codes] ${Object.keys(catalog.entries).length} entries -> ${path.relative(WEB_ROOT, DEST)} (${output.length} bytes)`);
}

module.exports = { validate, transform, SOURCE, DEST, CATEGORIES, CONFIDENCES };

if (require.main === module) sync();
